import React from 'react';
import { CBatchPasteInput } from '@cloud-materials/common';

export default () => {
  return (
    <>
      <h4>预设校验：指定validatorMode=v4，校验输入是否为ipv4格式，校验失败的tag将被标红</h4>
      <CBatchPasteInput
        defaultValue={['192.168.0.1', '256.156.0.6', '12.12.33.0/33', '12.12.33.0/12']}
        validatorMode="v4"
        placeholder="输入合法的ipv4"
      />
      <h4>自定义校验：通过tagValidator自定义校验规则</h4>
      <CBatchPasteInput
        defaultValue={['hi', 'word']}
        tagValidator={value => {
          if (value.length < 3) {
            return false;
          }
          return true;
        }}
      />
    </>
  );
};

import React from 'react';
import { CBatchPasteInput, Tag } from '@cloud-materials/common';

export default () => {
  function tagRender(props: { value: any; label: React.ReactNode; closable: boolean; onClose: (event: any) => void }) {
    const { label, value, closable, onClose } = props;
    return (
      <Tag
        color={['arcoblue', 'orange', 'lime'].indexOf(value) > -1 ? value : 'gray'}
        closable={closable}
        onClose={onClose}
        style={{ margin: '2px 6px 2px 0' }}
      >
        {label}
      </Tag>
    );
  }
  return (
    <>
      <h4>
        用法同Arco InputTag的renderTag属性，使用该属性将覆盖tagValidator的自定义校验能力和validatorMode的预设校验能力
      </h4>
      <CBatchPasteInput defaultValue={['arcoblue', 'orange', 'lime']} renderTag={tagRender} />
    </>
  );
};

