import React, { useRef } from 'react';
import type { CBatchPasteInputProps } from '@cloud-materials/common';
import { CForm, CBatchPasteInput, Message, CModal, Button } from '@cloud-materials/common';
import type { CForm as CFormType } from '@cloud-materials/common/es/CForm';

const ipValidator = (options: { ip: string }) => {
  const { ip } = options;
  const illegalIpList = ['0.0.0.0', '255.255.255.255'];
  if (illegalIpList.includes(ip)) return false;
  return true;
};

export default () => {
  const form = useRef<CFormType>();

  const config = CForm.defineConfig({
    formLayout: {
      labelWidth: 200,
    },
    fields: [
      {
        name: 'required_1',
        title: '输入IP',
        initialValue: ['1.1.1.1'],
        decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
        required: true,
        componentOptions: CForm.defineComponentOption(({ value: totalValues, onChange }) => {
          const props: CBatchPasteInputProps = {
            value: totalValues,
            onChange,
            allowClear: true,
            validatorMode: 'whitelistIp' as const,
            placeholder: '请输入IP地址或地址段',
            // 校验规则form和tag的颜色及校验状态保持一致
            tagValidator: (value: string) => {
              return ipValidator({ ip: value });
            },
            onSplit(addedValue, valueBeforeAdd, valueAfterAdd) {
              const finalAddedLength = valueAfterAdd.length - valueBeforeAdd.length;
              const duplicatedLength = addedValue.length - finalAddedLength;
              duplicatedLength > 0 && Message.warning(`重复的 ${duplicatedLength} 个IP地址已为您自动清除，请检查`);
            },
            // * validate适用于单个输入，按回车的情况，不会触发onSplit
            validate(inputValue, values: { value: string }[]) {
              const isDuplicated = values.some(item => item.value === inputValue);
              isDuplicated && Message.warning('当前IP地址输入重复，请检查');
              return inputValue && values.every(item => item.value !== inputValue);
            },
            tagTips: '双击可编辑',
            arcoTagProps({ tagIndex }) {
              return {
                style: { cursor: 'pointer' },
                onDoubleClick() {
                  CModal.openForm({
                    title: '编辑IP',
                    formConfig: {
                      fields: [
                        {
                          name: 'ip',
                          title: 'IP',
                          decoratorOptions: CForm.defineDecoratorOptions('FormItem'),
                          componentOptions: CForm.defineComponentOption('Input'),
                          initialValue: totalValues[tagIndex],
                          required: true,
                          rules: [
                            {
                              validator: ({ value, callback }) => {
                                if (!ipValidator({ ip: value })) {
                                  return callback('请输入合法的IP地址或地址段');
                                }
                                const duplicatedIndex = totalValues?.findIndex((item: string) => item === value);
                                if (duplicatedIndex > -1 && duplicatedIndex !== tagIndex) {
                                  return callback('IP地址或地址段重复，请检查');
                                }
                                callback();
                              },
                            },
                          ],
                        },
                      ],
                    },
                    onOk(values) {
                      totalValues[tagIndex] = values.ip;
                      onChange([...totalValues]);
                    },
                  });
                },
              };
            },
          };
          return <CBatchPasteInput {...props} />;
        }),
      },
    ],
  });

  return (
    <div style={{ width: '100%', maxHeight: 1500, overflow: 'auto' }}>
      <CForm config={config} defaultDecoratorProps={{ isFullPage: false }} ref={form} />
      <Button
        type="primary"
        onClick={() => {
          form.current?.submit(values => {
            console.log('submit values', values);
          });
        }}
      >
        提交
      </Button>
    </div>
  );
};
